1. var builder = WebApplication.CreateBuilder(args);
2. builder.AddServiceDefaults();
3. builder.AddAzureOpenAIClient("openai");
4. builder.Services.AddSingleton<IChatClient>(sp =>
5.     sp.GetRequiredService<AzureOpenAIClient>()
6.       .GetChatClient(builder.Configuration["Model"])
7.       .AsIChatClient());
8. builder.Services.AddSingleton(sp => new ChatClientAgent(
9.     sp.GetRequiredService<IChatClient>(),
10.     instructions: "You are a concise coach."));
11. var app = builder.Build();
12. app.MapDefaultEndpoints();
13. app.MapPost("/chat", async (ChatClientAgent agent, string message) =>
14.     await agent.RunAsync(message));
15. app.Run();
16.

